// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Ultra Sound Money'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative geometric blocks — top-left cluster
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.15, h: 5.625,
    fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.25, y: 0, w: 0.06, h: 3.2,
    fill: { color: theme.secondary }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 3.5, h: 0.08,
    fill: { color: theme.accent }
  });

  // Bottom-right decorative cluster
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 9.85, y: 1.5, w: 0.15, h: 4.125,
    fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 5.545, w: 3.5, h: 0.08,
    fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 9.69, y: 0.5, w: 0.06, h: 2.5,
    fill: { color: theme.secondary }
  });

  // Main title
  slide.addText("ULTRA SOUND MONEY", {
    x: 0.6, y: 1.2, w: 8.8, h: 1.4,
    fontSize: 56, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left",
    charSpacing: 4
  });

  // Subtitle
  slide.addText("Ethereum's Post-Merge Supply Dynamics\nand Monetary Premium", {
    x: 0.6, y: 2.65, w: 7, h: 1.0,
    fontSize: 22, fontFace: "Calibri",
    color: "ffffff", align: "left",
    lineSpacingMultiple: 1.3
  });

  // Thin separator line
  slide.addShape(pres.shapes.LINE, {
    x: 0.6, y: 3.85, w: 2.5, h: 0,
    line: { color: theme.light, width: 2 }
  });

  // Context stats row
  slide.addText([
    { text: "121.6M ETH", options: { bold: true, color: theme.light, fontSize: 16, fontFace: "Georgia" } },
    { text: "  Supply   |   ", options: { color: "ffffff", fontSize: 14, fontFace: "Calibri" } },
    { text: "0.1 Gwei", options: { bold: true, color: theme.light, fontSize: 16, fontFace: "Georgia" } },
    { text: "  Gas   |   ", options: { color: "ffffff", fontSize: 14, fontFace: "Calibri" } },
    { text: "$2,243", options: { bold: true, color: theme.light, fontSize: 16, fontFace: "Georgia" } },
    { text: "  ETH Price", options: { color: "ffffff", fontSize: 14, fontFace: "Calibri" } }
  ], {
    x: 0.6, y: 4.1, w: 8, h: 0.5,
    align: "left", valign: "top"
  });

  // Source attribution
  slide.addText("Source: ultrasound.money", {
    x: 0.6, y: 5.0, w: 3, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "left"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "000814", secondary: "003566", accent: "ffc300", light: "ffd60a", bg: "001d3d" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

