// slide-02.js — Supply Change Snapshot (Data Visualization)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'ETH Supply Growing at +0.83%/Year'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("ETH Supply Growing at +0.83%/Year", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.55,
    fontSize: 28, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", fit: "shrink"
  });
  slide.addText("Only 192 ETH Burned in 7 Days Against 19,638 ETH Issued", {
    x: 0.4, y: 0.75, w: 9.2, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: "ffffff", align: "left"
  });

  // Bar chart — Issuance vs Burn
  const chartData = [
    { name: "7-Day Flow", labels: ["Issuance", "Burn"], values: [19638, 192] }
  ];
  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.3, w: 5.2, h: 3.4,
    barDir: "col",
    chartColors: [theme.accent, theme.secondary],
    chartArea: { fill: { color: theme.primary }, roundedCorners: true },
    catAxisLabelColor: "ffffff",
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: "ffffff",
    valAxisLabelFontSize: 9,
    valGridLine: { color: theme.secondary, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.light,
    dataLabelFontSize: 11,
    dataLabelFontFace: "Georgia",
    showLegend: false,
    valAxisNumFmt: "#,##0",
    plotArea: { fill: { color: theme.primary } }
  });

  // Right side — stat cards
  const cardX = 6.0;
  const cardW = 3.5;
  const cardH = 0.85;

  // Card 1: Current Supply
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.3, w: cardW, h: cardH,
    fill: { color: theme.primary }, rectRadius: 0.03
  });
  slide.addText("Current Supply", {
    x: cardX + 0.15, y: 1.35, w: cardW - 0.3, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: "ffffff", align: "left"
  });
  slide.addText("121,603,980 ETH", {
    x: cardX + 0.15, y: 1.55, w: cardW - 0.3, h: 0.45,
    fontSize: 20, fontFace: "Georgia", color: theme.accent, bold: true, align: "left"
  });

  // Card 2: Net 7-Day Change
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.35, w: cardW, h: cardH,
    fill: { color: theme.primary }, rectRadius: 0.03
  });
  slide.addText("Net 7-Day Change", {
    x: cardX + 0.15, y: 2.4, w: cardW - 0.3, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: "ffffff", align: "left"
  });
  slide.addText("+19,445.89 ETH", {
    x: cardX + 0.15, y: 2.6, w: cardW - 0.3, h: 0.45,
    fontSize: 20, fontFace: "Georgia", color: theme.light, bold: true, align: "left"
  });

  // Card 3: Burn / Issuance Offset
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 3.4, w: cardW, h: cardH,
    fill: { color: theme.primary }, rectRadius: 0.03
  });
  slide.addText("Burn / Issuance Offset", {
    x: cardX + 0.15, y: 3.45, w: cardW - 0.3, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: "ffffff", align: "left"
  });
  slide.addText("0.01x", {
    x: cardX + 0.15, y: 3.65, w: cardW - 0.3, h: 0.45,
    fontSize: 24, fontFace: "Georgia", color: "ff6b6b", bold: true, align: "left"
  });

  // Annotation below chart
  slide.addText("Burn offsets only ~1% of new issuance at current gas levels", {
    x: 0.4, y: 4.85, w: 5.2, h: 0.35,
    fontSize: 11, fontFace: "Calibri", color: "ffffff",
    align: "center", italic: true
  });

  // Annualized growth callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 4.5, w: cardW, h: 0.6,
    fill: { color: theme.secondary }, rectRadius: 0.03
  });
  slide.addText("Annualized Growth Rate", {
    x: cardX + 0.15, y: 4.52, w: cardW - 0.3, h: 0.22,
    fontSize: 9, fontFace: "Calibri", color: "ffffff", align: "left"
  });
  slide.addText("+0.83% / year", {
    x: cardX + 0.15, y: 4.72, w: cardW - 0.3, h: 0.3,
    fontSize: 16, fontFace: "Georgia", color: theme.light, bold: true, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "000814", secondary: "003566", accent: "ffc300", light: "ffd60a", bg: "001d3d" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

