// slide-06.js — Supply Projections (Data Visualization - Line Chart)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Long-Term Equilibrium at 125.7M ETH'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Long-Term Equilibrium at 125.7M ETH", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.55,
    fontSize: 26, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", fit: "shrink"
  });
  slide.addText("200-year supply trajectory with 1,037K ETH/year issuance-burn balance at equilibrium", {
    x: 0.4, y: 0.75, w: 9.2, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: "ffffff", align: "left"
  });

  // Line chart — 200-year supply projection
  // Model: S(t) = 125.7 - 4.1 * exp(-0.03 * t), starting from 121.6M at t=0
  const chartData = [
    {
      name: "ETH Supply (M)",
      labels: ["Now", "10yr", "20yr", "30yr", "50yr", "75yr", "100yr", "150yr", "200yr"],
      values: [121.6, 122.66, 123.45, 124.03, 124.79, 125.27, 125.50, 125.65, 125.69]
    },
    {
      name: "Equilibrium",
      labels: ["Now", "10yr", "20yr", "30yr", "50yr", "75yr", "100yr", "150yr", "200yr"],
      values: [125.7, 125.7, 125.7, 125.7, 125.7, 125.7, 125.7, 125.7, 125.7]
    }
  ];
  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.4, y: 1.15, w: 5.8, h: 3.5,
    chartColors: [theme.accent, theme.secondary],
    lineSize: 3,
    lineSmooth: true,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 5,
    chartArea: { fill: { color: theme.primary }, roundedCorners: true },
    catAxisLabelColor: "ffffff",
    catAxisLabelFontSize: 9,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: "ffffff",
    valAxisLabelFontSize: 9,
    valGridLine: { color: theme.secondary, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendColor: "ffffff",
    legendFontSize: 9,
    legendFontFace: "Calibri",
    valAxisMinVal: 121,
    valAxisMaxVal: 126,
    plotArea: { fill: { color: theme.primary } },
    valAxisNumFmt: "0.0"
  });

  // Right side — Key parameters and era transitions
  const rightX = 6.5;
  const rightW = 3.2;

  // Parameters card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.15, w: rightW, h: 1.9,
    fill: { color: theme.primary }, rectRadius: 0.05
  });
  slide.addText("Projection Parameters", {
    x: rightX + 0.12, y: 1.2, w: rightW - 0.24, h: 0.28,
    fontSize: 12, fontFace: "Georgia", color: theme.accent, bold: true, align: "left"
  });

  const params = [
    { label: "ETH Staked", value: "39M" },
    { label: "Base Gas Assumption", value: "22 Gwei" },
    { label: "PoS Issuance", value: "2.8K ETH/day" },
    { label: "Fee Burn", value: "2.2K ETH/day" },
    { label: "Equilibrium Burn", value: "1,037K ETH/yr" }
  ];
  params.forEach((p, i) => {
    const py = 1.52 + i * 0.28;
    slide.addText(p.label, {
      x: rightX + 0.12, y: py, w: 1.6, h: 0.22,
      fontSize: 9, fontFace: "Calibri", color: "ffffff", align: "left"
    });
    slide.addText(p.value, {
      x: rightX + 1.8, y: py, w: 1.2, h: 0.22,
      fontSize: 9, fontFace: "Georgia", color: theme.light, bold: true, align: "right"
    });
  });

  // Era transitions card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 3.2, w: rightW, h: 1.55,
    fill: { color: theme.primary }, rectRadius: 0.05
  });
  slide.addText("Historical Era Transitions", {
    x: rightX + 0.12, y: 3.25, w: rightW - 0.24, h: 0.28,
    fontSize: 12, fontFace: "Georgia", color: theme.accent, bold: true, align: "left"
  });

  const eras = [
    "Genesis: 5 ETH/block",
    "Byzantium: 3 ETH/block",
    "Constantinople: 2 ETH/block",
    "Phase 0: Staking begins",
    "London: EIP-1559 burn",
    "The Merge: PoW removed"
  ];
  eras.forEach((era, i) => {
    slide.addText(era, {
      x: rightX + 0.2, y: 3.55 + i * 0.19, w: rightW - 0.35, h: 0.19,
      fontSize: 8, fontFace: "Calibri", color: "ffffff", align: "left"
    });
  });

  // Bottom annotation
  slide.addText("Issuance rewards: 2.7%/yr for stakers | Effective burn rate: 1.2%/yr for non-stakers | Supply growth flattened dramatically post-merge", {
    x: 0.4, y: 4.85, w: 9.2, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: "ffffff", italic: true, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "000814", secondary: "003566", accent: "ffc300", light: "ffd60a", bg: "001d3d" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

