// compile.js — Assembles all slide modules into final PPTX
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'Ultra Sound Money Analytics';
pres.title = 'Ultra Sound Money: Ethereum\'s Post-Merge Supply Dynamics and Monetary Premium';

const theme = {
  primary: "000814",    // deep black-blue — dark shapes, overlays
  secondary: "003566",  // dark blue — card backgrounds, secondary elements
  accent: "ffc300",     // bright gold — key numbers, highlights
  light: "ffd60a",      // yellow — secondary highlights, emphasis
  bg: "001d3d"          // dark navy — slide backgrounds
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => { console.log('PPTX saved to ./output/final_deck.pptx'); })
  .catch(err => { console.error('Error:', err); process.exit(1); });

